service.description:
IronStone's record-lookup provider (Comms.xml shell-providers, boss.records) for the BasicComms Chat
            screens (plans/archive/Comms-Framework.md §3.3), over the user's own reach of the records:
            - info: for records, each record's {recordEntityName, recordId, entity, visible, title, typeLabel, url, icon}
              (ironstone.shared.ChatterServices.get#RecordInfo under the user's filters); one that cannot be read is logged and
              left out;
            - card: the record card of recordEntityName and recordId (get#RecordCard);
            - search: the records to file a message on for text (InboxServices.search#LinkRecords), as optionList;
            - links: the records the /qapps links of a message's body name (find#MessageRecords).

actions.script:
recordList = []
optionList = []
card = null
if (operation === 'info') {
    for (const wanted of Array.from(records || [])) {
        ec.message.pushErrors()
        try {
            const out = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: wanted.recordEntityName,
                recordId: wanted.recordId}).call()
            recordList.push({recordEntityName: wanted.recordEntityName, recordId: wanted.recordId,
                entity: out?.info?.recordEntityName || wanted.recordEntityName, visible: !!out?.visible, title: out?.visible ? out.title : null,
                typeLabel: out?.visible ? out.typeLabel : null, url: out?.visible ? (out.url || null) : null, icon: out?.icon || 'sym_o_description'})
        } catch (err) {
            ec.logger.warn(`Chat: the record ${wanted.recordEntityName} ${wanted.recordId} could not be read: ${err && err.message ? err.message : err}`)
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
} else if (operation === 'card') {
    card = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordCard').parameters({recordEntityName: recordEntityName,
        recordId: recordId}).call()?.card || null
} else if (operation === 'search') {
    optionList = Array.from(ec.service.sync().name('ironstone.comms.InboxServices.search#LinkRecords').parameter('term', text || '').call()?.optionList || [])
} else if (operation === 'links') {
    recordList = Array.from(ec.service.sync().name('ironstone.comms.ChatServices.find#MessageRecords').parameter('body', body || '').call()?.recordList || [])
}

recordList = []
const PARAMS = {workEffortId: 'mantle.work.effort.WorkEffort', requestId: 'mantle.request.Request', partyId: 'mantle.party.Party',
    orderId: 'mantle.order.OrderHeader', invoiceId: 'mantle.account.invoice.Invoice', paymentId: 'mantle.account.payment.Payment',
    shipmentId: 'mantle.shipment.Shipment', productId: 'mantle.product.Product', facilityId: 'mantle.facility.Facility',
    assetId: 'mantle.product.asset.Asset', communicationEventId: 'mantle.party.communication.CommunicationEvent'}
const seen = new Set()
for (const match of String(body || '').matchAll(/href="([^"]+)"/g)) {
    const href = String(match[1]).replace(/&amp;/g, '&')
    if (href.indexOf('/qapps/') < 0) continue
    const query = href.split('#')[0].split('?')[1] || ''
    for (const pair of query.split('&')) {
        const at = pair.indexOf('=')
        if (at <= 0) continue
        const name = pair.slice(0, at)
        let id = pair.slice(at + 1)
        try { id = decodeURIComponent(id.replace(/\+/g, ' ')) } catch (err) { continue }
        if (!PARAMS[name] || !id || id.length > 64) continue
        const key = PARAMS[name] + '|' + id
        if (seen.has(key)) continue
        seen.add(key)
        recordList.push({entity: PARAMS[name], id: id})
    }
    if (recordList.length >= 5) break
}
recordList = recordList.slice(0, 5)

if (kind === 'lead') {
    // Sales P5: a lead from the message, the user's (refused for a user without Sales: its services are BOSS_SALES')
    const made = ec.service.sync().name('ironstone.sales.ContextServices.create#LeadFromMessage').parameters({chatRoomId: chatRoomId || null,
        eventSeq: eventSeq, emailMessageId: emailMessageId || null, communicationEventId: communicationEventId || null}).call()
    if (ec.message.hasError()) return
    recordEntityName = made.recordEntityName
    recordId = made.recordId
    url = made.url
    message = made.message
    roomRecordLinked = false
    return
}
// the other kinds are a chat message's
if (!chatRoomId || eventSeq == null) { ec.message.addError('Which chat message?'); return }
if (kind === 'case') {
    const made = ec.service.sync().name('ironstone.customerservice.ChannelServices.create#CaseFromMessage').parameters({appRoot: 'CustomerService',
        kind: 'chat', chatRoomId: chatRoomId, eventSeq: eventSeq}).call()
    if (ec.message.hasError()) return
    recordEntityName = made.recordEntityName
    recordId = made.recordId
    url = made.url
    message = made.message
    roomRecordLinked = false
    return
}
if (kind === 'claimLine') {
    // People P15: the receipt in the user's own message added to their expense claim, a line to review there
    const added = ec.service.sync().name('mantle.humanres.ExpenseServices.create#ClaimLineFromChat').parameters({chatRoomId: chatRoomId,
        eventSeq: eventSeq}).call()
    if (ec.message.hasError()) return
    recordEntityName = 'mantle.humanres.expense.ExpenseClaim'
    recordId = added.invoiceId
    url = '/qapps/People/Expenses/ExpenseClaimDetail?invoiceId=' + encodeURIComponent(added.invoiceId)
    message = ec.resource.expand(added.created ? 'Added to your claim ${id}: check the expense there' : 'Already on your claim ${id}',
        '', {id: added.invoiceId})
    roomRecordLinked = false
    return
}
if (kind === 'application') {
    // People P16: the sender's application to an opening, a recruiter's (Mantle checks the recruiter, the room and the opening)
    const made = ec.service.sync().name('mantle.humanres.RecruitingServices.create#ApplicationFromChat').parameters({chatRoomId: chatRoomId,
        eventSeq: eventSeq}).call()
    if (ec.message.hasError()) return
    recordEntityName = 'mantle.humanres.employment.EmploymentApplication'
    recordId = made.employmentApplicationId
    url = '/qapps/People/Staffing/ApplicantDetail?employmentApplicationId=' + encodeURIComponent(made.employmentApplicationId)
    message = ec.resource.expand(made.created ? 'Application ${id} made from the message' : 'Already application ${id}',
        '', {id: made.employmentApplicationId})
    roomRecordLinked = false
    return
}
if (!['task', 'request', 'event'].includes(kind)) { ec.message.addError(`Create a task, request or event (or a case), not ${kind}`); return }
const out = ec.service.sync().name('mantle.party.CommunicationServices.create#RecordFromChatMessage').parameters({chatRoomId: chatRoomId,
    eventSeq: eventSeq, recordKind: kind}).call()
if (ec.message.hasError()) return
recordEntityName = out.recordEntityName
recordId = out.recordId
roomRecordLinked = !!out.roomRecordLinked
const link = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({recordEntityName: recordEntityName, id: recordId}).call()
url = link && link.url ? link.url : null
message = ec.resource.expand({task: 'Task ${id} made from the message', request: 'Request ${id} made from the message',
    event: 'Event ${id} made from the message'}[kind], '', {id: recordId}) + (roomRecordLinked ? ' ' + ec.l10n.localize('and linked to the room\'s record') : '')

filed = false
recordUrl = null
if (!chatActorId || eventSeq == null) return
const actor = ec.entity.find('moqui.chat.ChatActor').condition('chatActorId', chatActorId).disableAuthz().one()
const external = actor?.chatExternalUserId ? ec.entity.find('moqui.chat.ChatExternalUser')
    .condition('chatExternalUserId', actor.chatExternalUserId).disableAuthz().one() : null
if (!external?.externalUserId) return
const context = ec.service.sync().name('ironstone.comms.ComposeServices.get#CallContext').parameter('number', external.externalUserId).call()
if (ec.message.hasError()) return
const contacts = Array.from(context?.contactList || [])
if (contacts.length !== 1 || !contacts[0].partyId) return
const out = ec.service.sync().name('ironstone.comms.ChatServices.file#OnRecord').parameters({chatRoomId: chatRoomId, eventSeq: eventSeq,
    recordEntityName: 'mantle.party.Party', recordId: contacts[0].partyId}).call()
if (ec.message.hasError()) return
filed = true
recordUrl = out?.url || contacts[0].url || null
